import React, { useState, useEffect } from "react";
import { ExternalLink, Plus, RefreshCw, Download, List, ChevronUp, Loader2, SlidersHorizontal, Trash2 } from "lucide-react";
import { type ModalViewProps, formatFileSize } from "./types";
import { ModMediaCarousel, ModThumbnailStrip } from "./components/mod-media-carousel";
import Core from "@core";
import Utils from "@utils";
import { useDownloadStore, DownloadStatus } from "../../../../store";

interface DesktopViewProps extends ModalViewProps {
  carouselRef: React.RefObject<HTMLDivElement | null>;
  thumbnailsRef: React.RefObject<HTMLDivElement | null>;
}

/**
 * Desktop specific render for the Mod Details Modal.
 * Includes the 3D overlapping layout and dual absolute layers.
 */
export const DesktopView: React.FC<DesktopViewProps> = ({
  displayCard,
  engineName,
  formatDate,
  formatFullDate,
  activeIndex,
  handleScroll,
  scrollToIndex,
  prevImage,
  nextImage,
  carouselRef,
  thumbnailsRef,
}) => {
  const [hoverTooltip, setHoverTooltip] = useState<"submitted" | "updated" | null>(null);
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const [isInstalled, setIsInstalled] = useState(false);
  const [isUninstalling, setIsUninstalling] = useState(false);

  const downloadTasks = useDownloadStore((s) => s.tasks);
  const startDownloadTask = useDownloadStore((s) => s.startDownload);
  const cancelDownloadTask = useDownloadStore((s) => s.cancelDownload);

  const downloadProgress = React.useMemo(() => {
    const map: { [key: string]: number } = {};
    Object.keys(downloadTasks).forEach((key) => {
      map[key] = downloadTasks[key].progress;
    });
    return map;
  }, [downloadTasks]);

  const downloadStatus = React.useMemo(() => {
    const map: { [key: string]: string } = {};
    Object.keys(downloadTasks).forEach((key) => {
      map[key] = downloadTasks[key].status;
    });
    return map;
  }, [downloadTasks]);

  useEffect(() => {
    const checkInstall = async () => {
      if (displayCard.id) {
        try {
          const installed = await Core.platform.isModInstalled(displayCard.id.toString());
          setIsInstalled(installed);
        } catch (e) {
          console.warn("Could not check if mod is installed:", e);
        }
      }
    };
    checkInstall();
  }, [displayCard.id, downloadTasks]);

  const handleDownload = async (url: string, id: string) => {
    if (downloadTasks[id] !== undefined) {
      cancelDownloadTask(id);
      return;
    }
    
    if (!displayCard.id) return;
    const card = displayCard as any;
    const payload = {
      id: displayCard.id,
      gameId: card.gameId,
      title: displayCard.name,
      description: displayCard.description,
      htmlBody: displayCard.htmlBody,
      author: displayCard.author,
      userId: card.userId,
      userPfp: card.userPfp,
      authors: card.authors,
      likes: card.likes,
      views: card.views,
      downloads: card.downloads,
      submittedAt: card.submittedAt,
      updatedAt: card.updatedAt,
      timeAgo: card.timeAgo,
      thumbnail: card.thumbnail,
      isNsfw: card.isNsfw,
      previewMedia: card.previewMedia,
      files: displayCard.files,
      engineName: engineName,
      formatDate: formatDate,
      formatFullDate: formatFullDate,
    };

    await startDownloadTask({
      url,
      fileId: id,
      modId: displayCard.id.toString(),
      modName: displayCard.name,
      payload,
    });

    if (displayCard.id) {
      Core.platform.isModInstalled(displayCard.id.toString()).then(setIsInstalled).catch(() => {});
    }
  };

  const handleUninstall = async () => {
    if (!displayCard.id) return;
    setIsUninstalling(true);
    try {
      await Core.platform.uninstallMod(displayCard.id.toString());
      setIsInstalled(false);
      Utils.toast.success(`"${displayCard.name}" uninstalled successfully!`, {
        title: "Mod Uninstalled",
      });
    } catch (e: any) {
      console.warn("Error uninstalling:", e);
      Utils.toast.error(e?.message || "Failed to uninstall mod.", {
        title: "Uninstall Error",
      });
    } finally {
      setIsUninstalling(false);
    }
  };

  const isLoading = displayCard.files === undefined;
  const validFiles = Object.values(displayCard.files || {}).filter((file: any) => file._nFilesize >= 5 * 1024 * 1024);
  const hasMultipleFiles = validFiles.length > 1;
  const hasNoFiles = validFiles.length === 0;
  
  const singleFileId = validFiles[0]?._idRow;
  const singleFileProgress = singleFileId ? downloadProgress[singleFileId] : undefined;
  const singleFileStatus = singleFileId ? downloadStatus[singleFileId] : undefined;

  return (
    <div className="hidden md:block w-full h-full relative">
      {displayCard && displayCard.previewMedia && displayCard.previewMedia.length > 1 && (
        <div className="absolute top-[60%] md:top-[55%] bottom-6 left-2 md:bottom-10 md:left-4 w-[calc(100%-1rem)] md:w-[calc(60%+3rem)] p-4 md:p-6 md:pr-16 md:pt-12 z-0 flex items-end justify-start pointer-events-auto bg-[var(--wb-surface-container-lowest)] rounded-bl-3xl">
          <ModThumbnailStrip
            media={displayCard.previewMedia}
            activeIndex={activeIndex}
            onSelectIndex={scrollToIndex}
            stripRef={thumbnailsRef}
            onPrev={prevImage}
            onNext={nextImage}
            variant="desktop"
          />
        </div>
      )}

      <div className="flex flex-col h-full overflow-hidden text-[var(--wb-on-surface)] w-full relative z-10 filter drop-shadow-[0_8px_32px_rgba(0,0,0,0.6)] pointer-events-none">
        <div className="relative flex items-center px-4 md:px-6 pt-2 pb-3 md:pt-3 md:pb-4 shrink-0 bg-[var(--wb-surface-container)] min-h-[56px] pr-16 md:pr-4 rounded-t-2xl pointer-events-auto">
          <div className="flex items-center gap-2 md:gap-3 flex-wrap z-10">
            <a href={`https://gamebanana.com/mods/${displayCard.id}`} target="_blank" rel="noopener noreferrer" className="flex items-center justify-center w-8 h-8 md:w-10 md:h-10 rounded-full bg-[var(--wb-surface-bright)] hover:bg-white/10 transition-colors relative group shrink-0">
              <img src="/assets/icons/app/gamebanana.webp" alt="GameBanana" className="w-4 h-4 md:w-5 md:h-5 object-contain opacity-80" />
              <div className="absolute -bottom-1 -right-1 bg-[var(--wb-surface-container)] rounded-full p-[2px]">
                <ExternalLink className="w-3 h-3 text-[var(--wb-on-surface-variant)] group-hover:text-[var(--wb-on-surface)]" />
              </div>
            </a>
            <div className="w-[1px] h-6 bg-white/10 mx-1" />
            {displayCard.icon && (
              <div className="flex items-center gap-2 px-3 md:px-4 py-1.5 rounded-full bg-[#6434d4]/20 text-[#ab8af1] border border-[#6434d4]/30 shrink-0">
                <img src={displayCard.icon} alt={engineName} className="w-4 h-4 object-contain brightness-150" />
                <span className="text-xs md:text-sm font-semibold">{engineName}</span>
              </div>
            )}
          </div>
          <div className="absolute inset-0 flex items-center justify-center pointer-events-none hidden md:flex">
            <div className="flex items-center gap-2 pointer-events-auto shrink-0">
              <div 
                className="relative flex items-center gap-1.5 px-3 py-1.5 rounded-full bg-[var(--wb-surface-bright)] border border-white/10 text-[var(--wb-on-surface-variant)] text-sm select-none cursor-default"
                onMouseEnter={() => setHoverTooltip("submitted")}
                onMouseLeave={() => setHoverTooltip(null)}
              >
                <Plus className="w-3.5 h-3.5" />
                <span>{formatDate(displayCard.submittedAt)}</span>
                <div className={`absolute left-1/2 top-full -translate-x-1/2 mt-2 z-[100] pointer-events-none transition-opacity duration-200 flex flex-col items-center ${hoverTooltip === "submitted" ? "opacity-100" : "opacity-0"}`}>
                  <div className="w-0 h-0 border-l-[4px] border-l-transparent border-r-[4px] border-r-transparent border-b-[4px] border-b-black/90"></div>
                  <div className="bg-black/90 text-[var(--wb-text-main)] text-xs font-semibold px-3 py-1.5 rounded-lg whitespace-nowrap shadow-lg">
                    Submitted: {formatFullDate(displayCard.submittedAt)}
                  </div>
                </div>
              </div>

              {displayCard.updatedAt && displayCard.updatedAt !== displayCard.submittedAt && (
                <div 
                  className="relative flex items-center gap-1.5 px-3 py-1.5 rounded-full bg-[var(--wb-surface-bright)] border border-white/10 text-[var(--wb-on-surface-variant)] text-sm select-none cursor-default"
                  onMouseEnter={() => setHoverTooltip("updated")}
                  onMouseLeave={() => setHoverTooltip(null)}
                >
                  <RefreshCw className="w-3.5 h-3.5" />
                  <span>{formatDate(displayCard.updatedAt)}</span>
                  <div className={`absolute left-1/2 top-full -translate-x-1/2 mt-2 z-[100] pointer-events-none transition-opacity duration-200 flex flex-col items-center ${hoverTooltip === "updated" ? "opacity-100" : "opacity-0"}`}>
                    <div className="w-0 h-0 border-l-[4px] border-l-transparent border-r-[4px] border-r-transparent border-b-[4px] border-b-black/90"></div>
                    <div className="bg-black/90 text-[var(--wb-text-main)] text-xs font-semibold px-3 py-1.5 rounded-lg whitespace-nowrap shadow-lg">
                      Updated: {formatFullDate(displayCard.updatedAt)}
                    </div>
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>

        <div className="flex flex-col md:flex-row flex-1 w-full relative z-10 min-h-0">
          <div className="w-full md:w-[60%] flex flex-col shrink-0 relative z-10 min-h-0">
            <div className="w-full bg-[var(--wb-surface-container)] rounded-bl-2xl flex flex-col p-4 md:p-6 pb-6 md:pb-8 relative pointer-events-auto">
              <ModMediaCarousel
                media={displayCard.previewMedia}
                fallbackImage={displayCard.img}
                title={displayCard.name}
                showCaption={true}
                carouselRef={carouselRef}
                onScroll={handleScroll}
                onPrev={prevImage}
                onNext={nextImage}
              />
              <div className="absolute -bottom-6 -right-[1px] w-[calc(1.5rem+1px)] h-6 pointer-events-none hidden md:block">
                 <svg viewBox="0 0 24 24" className="w-full h-full fill-[var(--wb-surface-container)]" preserveAspectRatio="none"><path d="M 0 0 C 13 0 24 11 24 24 L 24 0 Z" /></svg>
              </div>
            </div>
          </div>

          <div className="w-full md:w-[40%] flex flex-col bg-[var(--wb-surface-container)] p-4 md:p-6 overflow-hidden relative rounded-b-2xl z-0 min-h-0 h-full pointer-events-auto">
            <div className="flex-1 overflow-y-auto custom-scrollbar flex flex-col min-h-0">
              <h1 className="text-2xl md:text-3xl lg:text-4xl font-bold text-[var(--wb-on-surface)] leading-tight font-display break-words">{displayCard.name}</h1>
              <span className="text-[var(--wb-on-surface-variant)] text-xs md:text-sm mt-1">by {displayCard.author || "Unknown"}</span>
              <hr className="border-white/10 my-4 md:my-6" />
              {displayCard.htmlBody ? (
                <div className="text-[var(--wb-on-surface-variant)] prose prose-invert prose-sm md:prose-base max-w-full pb-4 overflow-x-hidden break-words [&_*]:max-w-full [&_pre]:whitespace-pre-wrap [&_pre]:break-words [&_table]:block [&_table]:overflow-x-auto" dangerouslySetInnerHTML={{ __html: displayCard.htmlBody }} />
              ) : (
                <p className="text-[var(--wb-on-surface-variant)] text-sm md:text-base pb-4 break-words">{displayCard.description}</p>
              )}
            </div>
            <div 
              className="pt-4 md:pt-6 mt-auto shrink-0 bg-[var(--wb-surface-container)]"
              onMouseLeave={() => setIsDropdownOpen(false)}
            >
              <div className="relative w-full">
                {isInstalled ? (
                  <div className="flex gap-3 w-full">
                    <button className="flex-1 bg-[var(--wb-primary)] hover:opacity-90 text-[var(--wb-on-primary)] py-3 md:py-4 rounded-xl flex items-center justify-center gap-2 md:gap-3 px-6 transition-all duration-300 font-bold">
                      <SlidersHorizontal className="w-5 h-5 md:w-6 md:h-6" />
                      <span className="text-base md:text-lg">Manage</span>
                    </button>
                    <button 
                      onClick={handleUninstall}
                      disabled={isUninstalling}
                      className="flex-1 bg-red-500/10 hover:bg-red-500/20 text-red-400 py-3 md:py-4 rounded-xl flex items-center justify-center gap-2 md:gap-3 px-6 transition-all duration-300 font-bold border border-red-500/20"
                    >
                      {isUninstalling ? (
                        <Loader2 className="w-5 h-5 md:w-6 md:h-6 animate-spin" />
                      ) : (
                        <Trash2 className="w-5 h-5 md:w-6 md:h-6" />
                      )}
                      <span className="text-base md:text-lg">{isUninstalling ? "Uninstalling..." : "Uninstall"}</span>
                    </button>
                  </div>
                ) : (
                  <>
                    {hasMultipleFiles && isDropdownOpen && (
                      <div className="absolute bottom-[calc(100%+2px)] left-0 w-full bg-[var(--wb-surface-bright)] border border-white/10 rounded-xl shadow-lg flex flex-col overflow-hidden z-50">
                        {validFiles.map((file: any) => {
                          const prog = downloadProgress[file._idRow];
                          const status = downloadStatus[file._idRow];
                          const isDownloading = prog !== undefined && prog >= 0 && prog < 100;
                          const isCanceling = prog === -1;
                          return (
                            <button 
                              key={file._idRow} 
                              onClick={() => handleDownload(file._sDownloadUrl, file._idRow.toString())} 
                              className={`text-left px-4 py-3 hover:bg-white/5 border-b border-white/5 last:border-0 flex flex-col gap-1 transition-colors relative overflow-hidden ${isCanceling ? "cursor-wait opacity-80" : "group"}`}
                              disabled={isCanceling}
                            >
                              {prog !== undefined && prog >= 0 && (
                                <div className="absolute inset-0 bg-[var(--wb-primary)] opacity-20 pointer-events-none transition-all duration-300" style={{ width: `${prog}%` }} />
                              )}
                              {isDownloading && (
                                <div className="absolute inset-0 bg-red-500/90 flex flex-col items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity duration-200 z-20">
                                  <span className="text-white font-bold text-sm">Cancel Download</span>
                                </div>
                              )}
                                <span className={`text-sm font-semibold truncate w-full text-[var(--wb-on-surface)] relative z-10 transition-opacity ${isDownloading ? "group-hover:opacity-0" : ""}`}>
                                  {isCanceling
                                    ? "Canceling..."
                                    : prog !== undefined
                                    ? prog === 100
                                      ? "Completed"
                                      : status && status !== DownloadStatus.DOWNLOADING
                                      ? status
                                      : prog === 99
                                      ? "Extracting archive..."
                                      : `Downloading... ${prog}%`
                                    : file._sFile}
                                </span>
                              <span className={`text-xs text-[var(--wb-on-surface-variant)] relative z-10 transition-opacity ${isDownloading ? "group-hover:opacity-0" : ""}`}>{Math.round(file._nFilesize / 1024 / 1024)} MB - {file._nDownloadCount} downloads</span>
                            </button>
                          );
                        })}
                      </div>
                    )}
                    {isLoading ? (
                      <button 
                        disabled
                        className="w-full bg-[var(--wb-primary)] text-[var(--wb-on-primary)] py-3 md:py-4 rounded-xl flex items-center justify-center gap-2 md:gap-3 px-6 font-bold opacity-80 cursor-wait"
                      >
                        <Loader2 className="w-5 h-5 md:w-6 md:h-6 animate-spin" />
                        <span className="text-base md:text-lg">Loading...</span>
                      </button>
                    ) : hasNoFiles ? (
                      <button 
                        disabled
                        className="w-full bg-[var(--wb-surface-variant)] text-[var(--wb-on-surface-variant)] cursor-not-allowed py-3 md:py-4 rounded-xl flex items-center justify-center gap-2 md:gap-3 px-6 font-bold opacity-60 select-none pointer-events-auto transition-none shadow-none hover:bg-[var(--wb-surface-variant)] hover:opacity-60 hover:transform-none active:transform-none"
                      >
                        <Download className="w-5 h-5 md:w-6 md:h-6 pointer-events-none" />
                        <span className="text-base md:text-lg pointer-events-none">No downloads available</span>
                      </button>
                    ) : (
                      <button 
                        onClick={() => {
                          if (hasMultipleFiles) {
                            setIsDropdownOpen(!isDropdownOpen);
                          } else if (validFiles.length === 1) {
                            handleDownload(validFiles[0]._sDownloadUrl, validFiles[0]._idRow.toString());
                          }
                        }}
                        disabled={!hasMultipleFiles && singleFileProgress === -1}
                        className={`${!hasMultipleFiles && singleFileProgress === -1 ? "opacity-80 cursor-wait" : "group"} relative w-full bg-[var(--wb-primary)] hover:opacity-90 text-[var(--wb-on-primary)] py-3 md:py-4 rounded-xl flex items-center justify-center px-6 transition-all duration-300 font-bold overflow-hidden`}
                      >
                        {!hasMultipleFiles && singleFileProgress !== undefined && singleFileProgress >= 0 && (
                          <div 
                            className="absolute left-0 top-0 bottom-0 bg-black/20 pointer-events-none transition-all duration-300" 
                            style={{ width: `${singleFileProgress}%` }} 
                          />
                        )}
                        
                        {!hasMultipleFiles && singleFileProgress !== undefined && singleFileProgress >= 0 && singleFileProgress < 100 && (
                          <div className="absolute inset-0 bg-red-500 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity duration-200 z-20">
                            <span className="text-white font-bold text-base md:text-lg">Cancel Download</span>
                          </div>
                        )}
                        
                        {hasMultipleFiles ? (
                          <>
                            <div className="flex items-center justify-center gap-2 md:gap-3 relative z-10">
                              <List className="w-5 h-5 md:w-6 md:h-6" />
                              <span className="text-base md:text-lg">Multiple Files</span>
                            </div>
                            <ChevronUp className={`absolute right-6 w-5 h-5 md:w-6 md:h-6 transition-transform relative z-10 ${isDropdownOpen ? "rotate-180" : ""}`} />
                          </>
                        ) : (
                          <div className={`flex items-center justify-center gap-2 md:gap-3 relative z-10 transition-opacity duration-200 ${singleFileProgress !== undefined && singleFileProgress >= 0 && singleFileProgress < 100 ? "group-hover:opacity-0" : ""}`}>
                            {singleFileProgress === -1 ? (
                              <>
                                <Loader2 className="w-5 h-5 md:w-6 md:h-6 animate-spin opacity-80" />
                                <span className="text-base md:text-lg">Canceling...</span>
                              </>
                            ) : singleFileProgress === 100 ? (
                              <span className="text-base md:text-lg">Completed</span>
                            ) : (singleFileStatus && singleFileStatus !== DownloadStatus.DOWNLOADING) || singleFileProgress === 99 ? (
                              <>
                                <Loader2 className="w-5 h-5 md:w-6 md:h-6 animate-spin" />
                                <span className="text-base md:text-lg">{singleFileStatus || "Extracting archive..."}</span>
                              </>
                            ) : singleFileProgress !== undefined ? (
                              <>
                                <Loader2 className="w-5 h-5 md:w-6 md:h-6 animate-spin" />
                                <span className="text-base md:text-lg">Downloading... {singleFileProgress}%</span>
                              </>
                            ) : (
                              <>
                                <Download className="w-5 h-5 md:w-6 md:h-6 shrink-0" />
                                <div className="flex flex-col items-start leading-tight">
                                  <span className="text-base md:text-lg leading-tight">Download</span>
                                  {validFiles[0]?._nFilesize ? (
                                    <span className="text-xs font-normal opacity-80 leading-none mt-0.5">
                                      {formatFileSize(validFiles[0]._nFilesize)}
                                    </span>
                                  ) : null}
                                </div>
                              </>
                            )}
                          </div>
                        )}
                      </button>
                    )}
                  </>
                )}
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};
